// Read fetches the current InterfaceOpenvpn config from VyOS.
func (InterfaceOpenvpn) Read(
	ctx context.Context,
	req infer.ReadRequest[InterfaceOpenvpnArgs, InterfaceOpenvpnState],
) (infer.ReadResponse[InterfaceOpenvpnArgs, InterfaceOpenvpnState], error) {
	client := getClient(ctx)
	base := interfaceOpenvpnBasePath(req.State.Name)

	data, err := client.ShowConfig(ctx, pathToStrings(base))
	if err != nil {
		if isEmptyConfigError(err) {
			// Tag node exists but has no child properties. Return minimal state.
			args := InterfaceOpenvpnArgs{Name: req.State.Name}
			state := InterfaceOpenvpnState{InterfaceOpenvpnArgs: args}
			return infer.ReadResponse[InterfaceOpenvpnArgs, InterfaceOpenvpnState]{
				ID:     req.State.Name,
				Inputs: args,
				State:  state,
			}, nil
		}
		return infer.ReadResponse[InterfaceOpenvpnArgs, InterfaceOpenvpnState]{},
			fmt.Errorf("read InterfaceOpenvpn %s: %w", req.State.Name, err)
	}

	args, err := parseInterfaceOpenvpnConfig(req.State.Name, data)
	if err != nil {
		return infer.ReadResponse[InterfaceOpenvpnArgs, InterfaceOpenvpnState]{},
			fmt.Errorf("parse InterfaceOpenvpn %s config: %w", req.State.Name, err)
	}

	state := InterfaceOpenvpnState{InterfaceOpenvpnArgs: args}
	return infer.ReadResponse[InterfaceOpenvpnArgs, InterfaceOpenvpnState]{
		ID:     req.State.Name,
		Inputs: args,
		State:  state,
	}, nil
}

// Update modifies an existing InterfaceOpenvpn configuration.
func (InterfaceOpenvpn) Update(
	ctx context.Context,
	req infer.UpdateRequest[InterfaceOpenvpnArgs, InterfaceOpenvpnState],
) (infer.UpdateResponse[InterfaceOpenvpnState], error) {
	if req.DryRun {
		return infer.UpdateResponse[InterfaceOpenvpnState]{
			Output: InterfaceOpenvpnState{InterfaceOpenvpnArgs: req.Inputs},
		}, nil
	}

	ops := buildInterfaceOpenvpnUpdateOps(req.State.InterfaceOpenvpnArgs, req.Inputs)
	if len(ops) > 0 {
		client := getClient(ctx)
		if err := client.BatchConfigure(ctx, ops); err != nil {
			return infer.UpdateResponse[InterfaceOpenvpnState]{},
				fmt.Errorf("update InterfaceOpenvpn %s: %w", req.Inputs.Name, err)
		}
		saveIfEnabled(ctx)
	}

	return infer.UpdateResponse[InterfaceOpenvpnState]{
		Output: InterfaceOpenvpnState{InterfaceOpenvpnArgs: req.Inputs},
	}, nil
}

// Delete removes the InterfaceOpenvpn configuration from VyOS.
func (InterfaceOpenvpn) Delete(
	ctx context.Context,
	req infer.DeleteRequest[InterfaceOpenvpnState],
) (infer.DeleteResponse, error) {
	client := getClient(ctx)
	base := interfaceOpenvpnBasePath(req.State.Name)
	if err := client.Delete(ctx, pathToStrings(base)); err != nil {
		return infer.DeleteResponse{}, fmt.Errorf("delete InterfaceOpenvpn %s: %w", req.State.Name, err)
	}
	saveIfEnabled(ctx)
	return infer.DeleteResponse{}, nil
}

